package cl.sonidovivo;

import io.swagger.v3.oas.annotations.tags.Tag; import io.swagger.v3.oas.annotations.security.SecurityRequirement; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;

@RestController @RequestMapping("/auth") @Tag(name="Autenticación") class AuthController {private final AuthService service;AuthController(AuthService s){service=s;}@PostMapping("/login") AuthResponse login(@Valid @RequestBody LoginRequest request){return service.login(request);}@PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) UsuarioResponse registro(@Valid @RequestBody RegistroRequest request){return service.registro(request);}}
@RestController @RequestMapping("/api/productos") @Tag(name="Productos") class ProductoController {private final ProductoService service;ProductoController(ProductoService s){service=s;}@GetMapping Page<ProductoResponse> listar(@RequestParam(required=false)String busqueda,@RequestParam(required=false)String categoria,@RequestParam(required=false)String stock,@RequestParam(required=false)String orden,@RequestParam(defaultValue="0")int pagina,@RequestParam(defaultValue="12")int tamanio){return service.listar(busqueda,categoria,stock,orden,pagina,tamanio);}@GetMapping("/{id}") ProductoResponse uno(@PathVariable Long id){return service.uno(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="bearerAuth") ProductoResponse crear(@Valid @RequestBody ProductoRequest r){return service.crear(r);}@PutMapping("/{id}") @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="bearerAuth") ProductoResponse actualizar(@PathVariable Long id,@Valid @RequestBody ProductoRequest r){return service.actualizar(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="bearerAuth") void eliminar(@PathVariable Long id){service.eliminar(id);}}
@RestController @RequestMapping("/api/pedidos") @Tag(name="Pedidos") @SecurityRequirement(name="bearerAuth") class PedidoController {private final PedidoService service;PedidoController(PedidoService s){service=s;}@GetMapping @PreAuthorize("hasRole('CLIENTE')") List<PedidoResponse> listar(Authentication a){return service.listarCliente(a.getName());}@GetMapping("/{id}") @PreAuthorize("hasAnyRole('CLIENTE','ADMIN','VENDEDOR')") PedidoResponse detalle(@PathVariable Long id,Authentication a){return service.detalle(id,a.getName(),a.getAuthorities().stream().anyMatch(x->!x.getAuthority().equals("ROLE_CLIENTE")));}@PostMapping @ResponseStatus(HttpStatus.CREATED) @PreAuthorize("hasRole('CLIENTE')") PedidoResponse crear(Authentication a,@Valid @RequestBody PedidoRequest r){return service.crear(a.getName(),r);}@PutMapping("/{id}/estado") @PreAuthorize("hasAnyRole('ADMIN','VENDEDOR')") PedidoResponse estado(@PathVariable Long id,@Valid @RequestBody CambioEstadoRequest r){return service.estado(id,r);}}
@RestController @RequestMapping("/api/usuarios") @Tag(name="Usuarios") @PreAuthorize("hasRole('ADMIN')") @SecurityRequirement(name="bearerAuth") class UsuarioController {private final UsuarioService service;UsuarioController(UsuarioService s){service=s;}@GetMapping List<UsuarioResponse> listar(){return service.listar();}@GetMapping("/{id}") UsuarioResponse uno(@PathVariable Long id){return service.uno(id);}@PutMapping("/{id}") UsuarioResponse actualizar(@PathVariable Long id,@Valid @RequestBody UsuarioRequest r){return service.actualizar(id,r);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void eliminar(@PathVariable Long id){service.eliminar(id);}}
@RestController @RequestMapping("/api") @Tag(name="Contacto y reparaciones") class MensajeController {private final MensajeService service;MensajeController(MensajeService s){service=s;}@PostMapping("/contacto") @ResponseStatus(HttpStatus.CREATED) MensajeResponse contacto(@Valid @RequestBody ContactoRequest r){return service.contacto(r);}@PostMapping("/reparaciones") @ResponseStatus(HttpStatus.CREATED) MensajeResponse reparacion(@Valid @RequestBody ReparacionRequest r){return service.reparacion(r);}@GetMapping("/mensajes") @PreAuthorize("hasAnyRole('VENDEDOR','ADMIN')") @SecurityRequirement(name="bearerAuth") List<MensajeResponse> mensajes(){return service.listar();}}